import{_ as e,o as a,c as r,ai as d}from"./chunks/framework.ampVZV4B.js";const p=JSON.parse('{"title":"Java · 03 框架与生态","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/java/03-frameworks.md","filePath":"tech-system/backend/java/03-frameworks.md"}'),o={name:"tech-system/backend/java/03-frameworks.md"};function i(l,t,s,n,h,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="java-·-03-框架与生态" tabindex="-1">Java · 03 框架与生态 <a class="header-anchor" href="#java-·-03-框架与生态" aria-label="Permalink to “Java · 03 框架与生态”">​</a></h1><blockquote><p>语言是 Java；<strong>批量交付业务默认靠 Spring 体系</strong>。这里谈「用什么干活」，不背组件清单。</p></blockquote><h2 id="_1-spring-解决了什么" tabindex="-1">1. Spring 解决了什么 <a class="header-anchor" href="#_1-spring-解决了什么" aria-label="Permalink to “1. Spring 解决了什么”">​</a></h2><p>在 Spring 之前，企业 Java 容易变成：自己拼工厂、自己管依赖、横切逻辑到处复制。</p><p>核心价值就两句：</p><ol><li><strong>IoC / DI</strong>：对象怎么创建、怎么装配，交给容器</li><li><strong>AOP</strong>：日志、事务、鉴权等横切逻辑统一处理</li></ol><p>没有这两点，就谈不上「Java 企业开发现代默认路径」。</p><h3 id="ioc-di-怎么看" tabindex="-1">IoC / DI 怎么看 <a class="header-anchor" href="#ioc-di-怎么看" aria-label="Permalink to “IoC / DI 怎么看”">​</a></h3><ul><li>本质是 <strong>解耦</strong>：业务类不自己 <code>new</code> 依赖</li><li>好处：可测、可替换、生命周期统一</li><li>代价：「魔法」变多——出问题要会看代理、循环依赖、注入失败原因</li></ul><p><strong>判断：</strong> 中小项目注解注入足够；过度玩 Bean 后置处理奇技淫巧，收益低。</p><hr><h2 id="_2-spring-boot-我真正依赖的点" tabindex="-1">2. Spring Boot：我真正依赖的点 <a class="header-anchor" href="#_2-spring-boot-我真正依赖的点" aria-label="Permalink to “2. Spring Boot：我真正依赖的点”">​</a></h2><p>Boot 不是新框架，是 <strong>约定 + 自动配置 + Starter</strong>，把「能跑起来」的成本压下去。</p><table tabindex="0"><thead><tr><th>能力</th><th>为何重要</th></tr></thead><tbody><tr><td>配置外置、多环境</td><td><code>dev/test/prod</code> 不改代码</td></tr><tr><td>内嵌容器</td><td>部署成 jar 即可，运维路径简单</td></tr><tr><td>Starter</td><td>依赖版本收敛，少踩兼容坑</td></tr><tr><td>Actuator / 默认日志 / 连接池</td><td>工程默认项，不必从零拼</td></tr></tbody></table><p><strong>判断：</strong> 新业务默认 Boot；纠结「纯 Spring XML」没有意义。懂 <strong>排除/覆盖自动配置</strong>，比背 starter 列表重要。</p><hr><h2 id="_3-web-mvc-与接口层" tabindex="-1">3. Web（MVC）与接口层 <a class="header-anchor" href="#_3-web-mvc-与接口层" aria-label="Permalink to “3. Web（MVC）与接口层”">​</a></h2><ul><li><code>@RestController</code> + 明确 DTO；校验（Bean Validation）放边界</li><li>统一错误码与异常处理（<code>@ControllerAdvice</code>），前端/调用方才好对接</li><li><strong>Controller 薄</strong>：鉴权通过后进 Service；别在接口方法里堆事务与远程调用</li><li>幂等、限流、签名：按开放程度加，开放 API 必做</li></ul><p>接口设计原则：字段稳定、错误可机读、超时与重试语义说清楚。</p><hr><h2 id="_4-持久化与数据访问" tabindex="-1">4. 持久化与数据访问 <a class="header-anchor" href="#_4-持久化与数据访问" aria-label="Permalink to “4. 持久化与数据访问”">​</a></h2><table tabindex="0"><thead><tr><th>选型</th><th>我的直觉</th></tr></thead><tbody><tr><td>MyBatis / MyBatis-Plus</td><td>默认：SQL 可控，适合复杂报表与既有库表</td></tr><tr><td>JPA / Hibernate</td><td>团队已有或 CRUD 极标准时可用；复杂 SQL 仍易绕回原生</td></tr><tr><td>动态数据源 / 读写分离</td><td>有真实读写压力与运维能力再上</td></tr></tbody></table><p>N+1、大结果集、无索引条件——框架救不了，要在 SQL 与表设计上解决。<br> 相关：<a href="/my-vitepress-site/tech-system/backend/problems/database.html">后端问题 · 数据库</a></p><hr><h2 id="_5-事务-最值钱的一块理解" tabindex="-1">5. 事务（最值钱的一块理解） <a class="header-anchor" href="#_5-事务-最值钱的一块理解" aria-label="Permalink to “5. 事务（最值钱的一块理解）”">​</a></h2><p>必须能讲清：</p><ul><li><code>@Transactional</code> <strong>靠代理</strong>；同类自调用常失效</li><li>异常被 <code>catch</code> 吃掉、方法非 <code>public</code>，都会让人误以为「加了注解就安全」</li><li>传播行为先精通 <code>REQUIRED</code> / <code>REQUIRES_NEW</code>，再扩展其它</li></ul><p><strong>判断：</strong></p><ul><li>事务保证「该在一个库事务里的事」</li><li><strong>跨服务</strong>靠状态机 / 补偿 / 本地消息表，不迷信分布式事务框架当银弹</li><li>长事务里不要调慢远程；先落库状态再异步</li></ul><p>相关：<a href="/my-vitepress-site/tech-system/backend/problems/distributed.html">后端问题 · 分布式</a></p><hr><h2 id="_6-缓存、任务、消息-生态常用件" tabindex="-1">6. 缓存、任务、消息（生态常用件） <a class="header-anchor" href="#_6-缓存、任务、消息-生态常用件" aria-label="Permalink to “6. 缓存、任务、消息（生态常用件）”">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>常见选择</th><th>原则</th></tr></thead><tbody><tr><td>缓存</td><td>Redis</td><td>先定更新/失效策略，再谈分布式锁</td></tr><tr><td>本地缓存</td><td>Caffeine 等</td><td>单机热点；注意与 Redis 双层一致性</td></tr><tr><td>定时任务</td><td><code>@Scheduled</code> → XXL-JOB</td><td>多实例要抢锁或用分布式调度</td></tr><tr><td>异步解耦</td><td>线程池 → MQ</td><td>有削峰/最终一致需求再上 MQ</td></tr></tbody></table><p>相关：<a href="/my-vitepress-site/redis/overview.html">Redis 面试</a> · <a href="/my-vitepress-site/tech-system/backend/problems/mq.html">后端问题 · MQ</a></p><hr><h2 id="_7-spring-cloud-用过-该用" tabindex="-1">7. Spring Cloud：用过 ≠ 该用 <a class="header-anchor" href="#_7-spring-cloud-用过-该用" aria-label="Permalink to “7. Spring Cloud：用过 ≠ 该用”">​</a></h2><table tabindex="0"><thead><tr><th>组件方向</th><th>何时才值得</th></tr></thead><tbody><tr><td>注册/配置（Nacos 等）</td><td>已经多服务、要集中配置与发现</td></tr><tr><td>Feign / Gateway</td><td>已有拆分，需要声明式调用与统一入口</td></tr><tr><td>限流熔断</td><td>有真实流量与依赖脆弱性</td></tr></tbody></table><p>拆服务解决的是 <strong>组织与独立演进</strong>，不是性能灵丹。<br> 中小团队：<strong>模块化单体 + 清晰边界</strong> 往往比一上来 Cloud 全家桶更稳。</p><p>我在悟空等项目里用过注册、配置、Feign、任务与网关限流——那是 <strong>已有架构约束下的维护与交付</strong>，不是每个新项目的默认起手式。</p><hr><h2 id="_8-一张表-我会怎么选" tabindex="-1">8. 一张表：我会怎么选 <a class="header-anchor" href="#_8-一张表-我会怎么选" aria-label="Permalink to “8. 一张表：我会怎么选”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>选择</th></tr></thead><tbody><tr><td>业务 API</td><td>Spring Boot + MyBatis-Plus（或团队既有 ORM）</td></tr><tr><td>缓存</td><td>Redis + 明确策略</td></tr><tr><td>任务</td><td>本地异步 / XXL-JOB / 队列，按可靠性升</td></tr><tr><td>AI 编排</td><td>Java 管状态与配额；Python 管模型胶水</td></tr><tr><td>拆服务</td><td>默认不拆；Cloud 组件仅在已有约束时用</td></tr></tbody></table><p>下一篇：<a href="./04-engineering.html">04 工程实践</a></p>',43)])])}const g=e(o,[["render",i]]);export{p as __pageData,g as default};
